-- Quest completion texts (quest_offer_reward) and progress texts (quest_request_items) that our world lacked, word for word
-- as players' games showed them on the live realm.
-- Data from Efficient Games (https://efficient.games), licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).
-- Source: EG Link output, github.com/JIVESCORP/eg-link-output-wowf commit 9fcae73c (data to 2026-11-10), texts.enUS.json,
-- newest live build first (70862, 70840, 70790, older live builds, then the Forever beta), the variant most players saw. Changed: line breaks written as $B,
-- rows written as TrinityCore rows. Only quests with no row here, or with the placeholder row of 2026_11_08_20
-- (VerifiedBuild -1), get one; a real existing text is never replaced. VerifiedBuild = the build the text was seen on.
-- Safe to run again.

-- 1) completion texts (77 quests)
-- (no placeholder rows among them)
ON DUPLICATE KEY UPDATE `ID`=`ID`;

-- 2) progress texts (41 quests)
ON DUPLICATE KEY UPDATE `ID`=`ID`;

-- 3) Quest items of the quest objects of Vrang's Game (95507), Parts and Pieces (97253) and For Honor (96822), as the
--    server sends them (EG Link object_details.enUS, 70862/70840/70790): the client marks these objects as lootable for
--    the quest. Their loot already drops the items here.
DELETE FROM `gameobject_questitem` WHERE `GameObjectEntry` IN (640104,660930,656180,656181,656182);
